114	);
115	
116	parameter CL_S_COUNT = $clog2(S_COUNT);
117	
118	reg frame_reg = 1'b0, frame_next;
119	
120	reg [S_COUNT-1:0] s_ip_hdr_ready_reg = {S_COUNT{1'b0}}, s_ip_hdr_ready_next;
121	
122	reg m_ip_hdr_valid_reg = 1'b0, m_ip_hdr_valid_next;
123	reg [47:0] m_eth_dest_mac_reg = 48'd0, m_eth_dest_mac_next;
124	reg [47:0] m_eth_src_mac_reg = 48'd0, m_eth_src_mac_next;
125	reg [15:0] m_eth_type_reg = 16'd0, m_eth_type_next;
126	reg [3:0]  m_ip_version_reg = 4'd0, m_ip_version_next;
127	reg [3:0]  m_ip_ihl_reg = 4'd0, m_ip_ihl_next;
128	reg [5:0]  m_ip_dscp_reg = 6'd0, m_ip_dscp_next;
129	reg [1:0]  m_ip_ecn_reg = 2'd0, m_ip_ecn_next;
130	reg [15:0] m_ip_length_reg = 16'd0, m_ip_length_next;
131	reg [15:0] m_ip_identification_reg = 16'd0, m_ip_identification_next;
132	reg [2:0]  m_ip_flags_reg = 3'd0, m_ip_flags_next;
133	reg [12:0] m_ip_fragment_offset_reg = 13'd0, m_ip_fragment_offset_next;
134	reg [7:0]  m_ip_ttl_reg = 8'd0, m_ip_ttl_next;
135	reg [7:0]  m_ip_protocol_reg = 8'd0, m_ip_protocol_next;
136	reg [15:0] m_ip_header_checksum_reg = 16'd0, m_ip_header_checksum_next;
137	reg [31:0] m_ip_source_ip_reg = 32'd0, m_ip_source_ip_next;
138	reg [31:0] m_ip_dest_ip_reg = 32'd0, m_ip_dest_ip_next;
139	
140	wire [S_COUNT-1:0] request;
141	wire [S_COUNT-1:0] acknowledge;
142	wire [S_COUNT-1:0] grant;
143	wire grant_valid;
144	wire [CL_S_COUNT-1:0] grant_encoded;
145	
146	// internal datapath
147	reg  [DATA_WIDTH-1:0] m_ip_payload_axis_tdata_int;
148	reg  [KEEP_WIDTH-1:0] m_ip_payload_axis_tkeep_int;
149	reg                   m_ip_payload_axis_tvalid_int;
150	reg                   m_ip_payload_axis_tready_int_reg = 1'b0;
151	reg                   m_ip_payload_axis_tlast_int;
152	reg  [ID_WIDTH-1:0]   m_ip_payload_axis_tid_int;
153	reg  [DEST_WIDTH-1:0] m_ip_payload_axis_tdest_int;
154	reg  [USER_WIDTH-1:0] m_ip_payload_axis_tuser_int;
155	wire                  m_ip_payload_axis_tready_int_early;
156	
157	assign s_ip_hdr_ready = s_ip_hdr_ready_reg;
158	
159	assign s_ip_payload_axis_tready = (m_ip_payload_axis_tready_int_reg && grant_valid) << grant_encoded;
160	
161	assign m_ip_hdr_valid = m_ip_hdr_valid_reg;
162	assign m_eth_dest_mac = m_eth_dest_mac_reg;
163	assign m_eth_src_mac = m_eth_src_mac_reg;
164	assign m_eth_type = m_eth_type_reg;
165	assign m_ip_version = m_ip_version_reg;
166	assign m_ip_ihl = m_ip_ihl_reg;
167	assign m_ip_dscp = m_ip_dscp_reg;
168	assign m_ip_ecn = m_ip_ecn_reg;
169	assign m_ip_length = m_ip_length_reg;
170	assign m_ip_identification = m_ip_identification_reg;
171	assign m_ip_flags = m_ip_flags_reg;
172	assign m_ip_fragment_offset = m_ip_fragment_offset_reg;
173	assign m_ip_ttl = m_ip_ttl_reg;
174	assign m_ip_protocol = m_ip_protocol_reg;
175	assign m_ip_header_checksum = m_ip_header_checksum_reg;
176	assign m_ip_source_ip = m_ip_source_ip_reg;
177	assign m_ip_dest_ip = m_ip_dest_ip_reg;
178	
179	// mux for incoming packet
180	wire [DATA_WIDTH-1:0] current_s_tdata  = s_ip_payload_axis_tdata[grant_encoded*DATA_WIDTH +: DATA_WIDTH];
181	wire [KEEP_WIDTH-1:0] current_s_tkeep  = s_ip_payload_axis_tkeep[grant_encoded*KEEP_WIDTH +: KEEP_WIDTH];
182	wire                  current_s_tvalid = s_ip_payload_axis_tvalid[grant_encoded];
183	wire                  current_s_tready = s_ip_payload_axis_tready[grant_encoded];
184	wire                  current_s_tlast  = s_ip_payload_axis_tlast[grant_encoded];
185	wire [ID_WIDTH-1:0]   current_s_tid    = s_ip_payload_axis_tid[grant_encoded*ID_WIDTH +: ID_WIDTH];
186	wire [DEST_WIDTH-1:0] current_s_tdest  = s_ip_payload_axis_tdest[grant_encoded*DEST_WIDTH +: DEST_WIDTH];
187	wire [USER_WIDTH-1:0] current_s_tuser  = s_ip_payload_axis_tuser[grant_encoded*USER_WIDTH +: USER_WIDTH];
188	
189	// arbiter instance
190	arbiter #(
191	    .PORTS(S_COUNT),
192	    .ARB_TYPE_ROUND_ROBIN(ARB_TYPE_ROUND_ROBIN),
193	    .ARB_BLOCK(1),
194	    .ARB_BLOCK_ACK(1),
195	    .ARB_LSB_HIGH_PRIORITY(ARB_LSB_HIGH_PRIORITY)
196	)
197	arb_inst (
198	    .clk(clk),
199	    .rst(rst),
200	    .request(request),
201	    .acknowledge(acknowledge),
202	    .grant(grant),
203	    .grant_valid(grant_valid),
204	    .grant_encoded(grant_encoded)
205	);
206	
207	assign request = s_ip_hdr_valid & ~grant;
208	assign acknowledge = grant & s_ip_payload_axis_tvalid & s_ip_payload_axis_tready & s_ip_payload_axis_tlast;
209	
210	always @* begin
211	    frame_next = frame_reg;
212	
213	    s_ip_hdr_ready_next = {S_COUNT{1'b0}};
214	
215	    m_ip_hdr_valid_next = m_ip_hdr_valid_reg && !m_ip_hdr_ready;
216	    m_eth_dest_mac_next = m_eth_dest_mac_reg;
217	    m_eth_src_mac_next = m_eth_src_mac_reg;
218	    m_eth_type_next = m_eth_type_reg;
219	    m_ip_version_next = m_ip_version_reg;
220	    m_ip_ihl_next = m_ip_ihl_reg;
221	    m_ip_dscp_next = m_ip_dscp_reg;
222	    m_ip_ecn_next = m_ip_ecn_reg;
223	    m_ip_length_next = m_ip_length_reg;
224	    m_ip_identification_next = m_ip_identification_reg;
225	    m_ip_flags_next = m_ip_flags_reg;
226	    m_ip_fragment_offset_next = m_ip_fragment_offset_reg;
227	    m_ip_ttl_next = m_ip_ttl_reg;
228	    m_ip_protocol_next = m_ip_protocol_reg;
229	    m_ip_header_checksum_next = m_ip_header_checksum_reg;
230	    m_ip_source_ip_next = m_ip_source_ip_reg;
231	    m_ip_dest_ip_next = m_ip_dest_ip_reg;
232	
233	    if (s_ip_payload_axis_tvalid[grant_encoded] && s_ip_payload_axis_tready[grant_encoded]) begin
234	        // end of frame detection
235	        if (s_ip_payload_axis_tlast[grant_encoded]) begin
236	            frame_next = 1'b0;
237	        end
238	    end
239	
240	    if (!frame_reg && grant_valid && (m_ip_hdr_ready || !m_ip_hdr_valid)) begin
241	        // start of frame
242	        frame_next = 1'b1;
243	
244	        s_ip_hdr_ready_next = grant;
245	
246	        m_ip_hdr_valid_next = 1'b1;
247	        m_eth_dest_mac_next = s_eth_dest_mac[grant_encoded*48 +: 48];
248	        m_eth_src_mac_next = s_eth_src_mac[grant_encoded*48 +: 48];
249	        m_eth_type_next = s_eth_type[grant_encoded*16 +: 16];
250	        m_ip_version_next = s_ip_version[grant_encoded*4 +: 4];
251	        m_ip_ihl_next = s_ip_ihl[grant_encoded*4 +: 4];
252	        m_ip_dscp_next = s_ip_dscp[grant_encoded*6 +: 6];
253	        m_ip_ecn_next = s_ip_ecn[grant_encoded*2 +: 2];
254	        m_ip_length_next = s_ip_length[grant_encoded*16 +: 16];
255	        m_ip_identification_next = s_ip_identification[grant_encoded*16 +: 16];
256	        m_ip_flags_next = s_ip_flags[grant_encoded*3 +: 3];
257	        m_ip_fragment_offset_next = s_ip_fragment_offset[grant_encoded*13 +: 13];
258	        m_ip_ttl_next = s_ip_ttl[grant_encoded*8 +: 8];
259	        m_ip_protocol_next = s_ip_protocol[grant_encoded*8 +: 8];
260	        m_ip_header_checksum_next = s_ip_header_checksum[grant_encoded*16 +: 16];
261	        m_ip_source_ip_next = s_ip_source_ip[grant_encoded*32 +: 32];
262	        m_ip_dest_ip_next = s_ip_dest_ip[grant_encoded*32 +: 32];
263	    end
264	
265	    // pass through selected packet data
266	    m_ip_payload_axis_tdata_int  = current_s_tdata;
267	    m_ip_payload_axis_tkeep_int  = current_s_tkeep;
268	    m_ip_payload_axis_tvalid_int = current_s_tvalid && m_ip_payload_axis_tready_int_reg && grant_valid;
269	    m_ip_payload_axis_tlast_int  = current_s_tlast;
270	    m_ip_payload_axis_tid_int    = current_s_tid;
271	    m_ip_payload_axis_tdest_int  = current_s_tdest;
272	    m_ip_payload_axis_tuser_int  = current_s_tuser;
273	end
274	
275	always @(posedge clk) begin
276	    frame_reg <= frame_next;
277	
278	    s_ip_hdr_ready_reg <= s_ip_hdr_ready_next;
279	
280	    m_ip_hdr_valid_reg <= m_ip_hdr_valid_next;
281	    m_eth_dest_mac_reg <= m_eth_dest_mac_next;
282	    m_eth_src_mac_reg <= m_eth_src_mac_next;
283	    m_eth_type_reg <= m_eth_type_next;
284	    m_ip_version_reg <= m_ip_version_next;
285	    m_ip_ihl_reg <= m_ip_ihl_next;
286	    m_ip_dscp_reg <= m_ip_dscp_next;
287	    m_ip_ecn_reg <= m_ip_ecn_next;
288	    m_ip_length_reg <= m_ip_length_next;
289	    m_ip_identification_reg <= m_ip_identification_next;
290	    m_ip_flags_reg <= m_ip_flags_next;
291	    m_ip_fragment_offset_reg <= m_ip_fragment_offset_next;
292	    m_ip_ttl_reg <= m_ip_ttl_next;
293	    m_ip_protocol_reg <= m_ip_protocol_next;
294	    m_ip_header_checksum_reg <= m_ip_header_checksum_next;
295	    m_ip_source_ip_reg <= m_ip_source_ip_next;
296	    m_ip_dest_ip_reg <= m_ip_dest_ip_next;
297	
298	    if (rst) begin
299	        frame_reg <= 1'b0;
300	        s_ip_hdr_ready_reg <= {S_COUNT{1'b0}};
301	        m_ip_hdr_valid_reg <= 1'b0;
302	    end
303	end
304	
305	// output datapath logic
306	reg [DATA_WIDTH-1:0] m_ip_payload_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
307	reg [KEEP_WIDTH-1:0] m_ip_payload_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
308	reg                  m_ip_payload_axis_tvalid_reg = 1'b0, m_ip_payload_axis_tvalid_next;
309	reg                  m_ip_payload_axis_tlast_reg  = 1'b0;
310	reg [ID_WIDTH-1:0]   m_ip_payload_axis_tid_reg    = {ID_WIDTH{1'b0}};
311	reg [DEST_WIDTH-1:0] m_ip_payload_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
312	reg [USER_WIDTH-1:0] m_ip_payload_axis_tuser_reg  = {USER_WIDTH{1'b0}};
313	
314	reg [DATA_WIDTH-1:0] temp_m_ip_payload_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
315	reg [KEEP_WIDTH-1:0] temp_m_ip_payload_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
316	reg                  temp_m_ip_payload_axis_tvalid_reg = 1'b0, temp_m_ip_payload_axis_tvalid_next;
317	reg                  temp_m_ip_payload_axis_tlast_reg  = 1'b0;
318	reg [ID_WIDTH-1:0]   temp_m_ip_payload_axis_tid_reg    = {ID_WIDTH{1'b0}};
319	reg [DEST_WIDTH-1:0] temp_m_ip_payload_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
320	reg [USER_WIDTH-1:0] temp_m_ip_payload_axis_tuser_reg  = {USER_WIDTH{1'b0}};
321	
322	// datapath control
323	reg store_axis_int_to_output;
324	reg store_axis_int_to_temp;
325	reg store_ip_payload_axis_temp_to_output;
326	
327	assign m_ip_payload_axis_tdata  = m_ip_payload_axis_tdata_reg;
328	assign m_ip_payload_axis_tkeep  = KEEP_ENABLE ? m_ip_payload_axis_tkeep_reg : {KEEP_WIDTH{1'b1}};
329	assign m_ip_payload_axis_tvalid = m_ip_payload_axis_tvalid_reg;
330	assign m_ip_payload_axis_tlast  = m_ip_payload_axis_tlast_reg;
331	assign m_ip_payload_axis_tid    = ID_ENABLE   ? m_ip_payload_axis_tid_reg   : {ID_WIDTH{1'b0}};
332	assign m_ip_payload_axis_tdest  = DEST_ENABLE ? m_ip_payload_axis_tdest_reg : {DEST_WIDTH{1'b0}};
333	assign m_ip_payload_axis_tuser  = USER_ENABLE ? m_ip_payload_axis_tuser_reg : {USER_WIDTH{1'b0}};
334	
335	// enable ready input next cycle if output is ready or if both output registers are empty
336	assign m_ip_payload_axis_tready_int_early = m_ip_payload_axis_tready || (!temp_m_ip_payload_axis_tvalid_reg && !m_ip_payload_axis_tvalid_reg);
337	
338	always @* begin
339	    // transfer sink ready state to source
340	    m_ip_payload_axis_tvalid_next = m_ip_payload_axis_tvalid_reg;
341	    temp_m_ip_payload_axis_tvalid_next = temp_m_ip_payload_axis_tvalid_reg;
342	
343	    store_axis_int_to_output = 1'b0;
344	    store_axis_int_to_temp = 1'b0;
345	    store_ip_payload_axis_temp_to_output = 1'b0;
346	
347	    if (m_ip_payload_axis_tready_int_reg) begin
348	        // input is ready
349	        if (m_ip_payload_axis_tready || !m_ip_payload_axis_tvalid_reg) begin
350	            // output is ready or currently not valid, transfer data to output
351	            m_ip_payload_axis_tvalid_next = m_ip_payload_axis_tvalid_int;
352	            store_axis_int_to_output = 1'b1;
353	        end else begin
354	            // output is not ready, store input in temp
355	            temp_m_ip_payload_axis_tvalid_next = m_ip_payload_axis_tvalid_int;
356	            store_axis_int_to_temp = 1'b1;
357	        end
358	    end else if (m_ip_payload_axis_tready) begin
359	        // input is not ready, but output is ready
360	        m_ip_payload_axis_tvalid_next = temp_m_ip_payload_axis_tvalid_reg;
361	        temp_m_ip_payload_axis_tvalid_next = 1'b0;
362	        store_ip_payload_axis_temp_to_output = 1'b1;
363	    end
364	end
365	
366	always @(posedge clk) begin
367	    m_ip_payload_axis_tvalid_reg <= m_ip_payload_axis_tvalid_next;
368	    m_ip_payload_axis_tready_int_reg <= m_ip_payload_axis_tready_int_early;
369	    temp_m_ip_payload_axis_tvalid_reg <= temp_m_ip_payload_axis_tvalid_next;
370	
371	    // datapath
372	    if (store_axis_int_to_output) begin
373	        m_ip_payload_axis_tdata_reg <= m_ip_payload_axis_tdata_int;
374	        m_ip_payload_axis_tkeep_reg <= m_ip_payload_axis_tkeep_int;
375	        m_ip_payload_axis_tlast_reg <= m_ip_payload_axis_tlast_int;
376	        m_ip_payload_axis_tid_reg   <= m_ip_payload_axis_tid_int;
377	        m_ip_payload_axis_tdest_reg <= m_ip_payload_axis_tdest_int;
378	        m_ip_payload_axis_tuser_reg <= m_ip_payload_axis_tuser_int;
379	    end else if (store_ip_payload_axis_temp_to_output) begin
380	        m_ip_payload_axis_tdata_reg <= temp_m_ip_payload_axis_tdata_reg;
381	        m_ip_payload_axis_tkeep_reg <= temp_m_ip_payload_axis_tkeep_reg;
382	        m_ip_payload_axis_tlast_reg <= temp_m_ip_payload_axis_tlast_reg;
383	        m_ip_payload_axis_tid_reg   <= temp_m_ip_payload_axis_tid_reg;
384	        m_ip_payload_axis_tdest_reg <= temp_m_ip_payload_axis_tdest_reg;
385	        m_ip_payload_axis_tuser_reg <= temp_m_ip_payload_axis_tuser_reg;
386	    end
387	
388	    if (store_axis_int_to_temp) begin
389	        temp_m_ip_payload_axis_tdata_reg <= m_ip_payload_axis_tdata_int;
390	        temp_m_ip_payload_axis_tkeep_reg <= m_ip_payload_axis_tkeep_int;
391	        temp_m_ip_payload_axis_tlast_reg <= m_ip_payload_axis_tlast_int;
392	        temp_m_ip_payload_axis_tid_reg   <= m_ip_payload_axis_tid_int;
393	        temp_m_ip_payload_axis_tdest_reg <= m_ip_payload_axis_tdest_int;
394	        temp_m_ip_payload_axis_tuser_reg <= m_ip_payload_axis_tuser_int;
395	    end
396	
397	    if (rst) begin
398	        m_ip_payload_axis_tvalid_reg <= 1'b0;
399	        m_ip_payload_axis_tready_int_reg <= 1'b0;
400	        temp_m_ip_payload_axis_tvalid_reg <= 1'b0;
401	    end
402	end
403	
404	endmodule
405	
406	`resetall
407

